/// <summary>
/// AVA/WEN/2025/05/15   AVA_013002_ResourceCalendar
/// </summary>
[DataContractAttribute]
class AVAUpdateResourceCalendarContract implements SysOperationValidatable
{
    private FromDate fromDate;
    private ToDate toDate;
    private CalendarId  calendarId;
    private WrkCtrId resourceId;
    private boolean fromReleaseStatus = false;

}

Method.Source:
[DataMemberAttribute]
public fromDate parmFromDate(fromDate _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

[DataMemberAttribute]
public ToDate parmToDate(ToDate _ToDate = ToDate)
{
    ToDate = _ToDate;
    return ToDate;
}

[DataMemberAttribute]
public CalendarId parmCalendarId(calendarId _calendarId = calendarId)
{
    calendarId = _calendarId;
    return calendarId;
}

public WrkCtrId parmResourceId(WrkCtrId _resourceId = resourceId)
{
    resourceId = _resourceId;
    return resourceId;
}

public boolean parmFromReleaseStatus(boolean _fromRelease = fromReleaseStatus)
{
    fromReleaseStatus = _fromRelease;
    return fromReleaseStatus;
}

public boolean validate()
{
    boolean isValid = true;

    if (!fromDate)
    {
        isValid = checkFailed("@NDX:NXAFromDateRequired");
    }

    if (fromDate && fromDate < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
    {
        isValid = checkFailed("@NDX:NXAFromDateNotPast");
    }

    if (fromDate && toDate && fromDate > toDate)
    {
        isValid = checkFailed("@NDX:NXAFromDateToDate");
    }

    return isValid;
}
